import {stages,caseData,priceList,discussionQuestions,personas} from './caseData.js';

const KEY='education2035-save-store-v2';
const blank=()=>({view:'map',stage:0,completed:[],evidence:[],answers:{},selection:{},decision:'',lockedDecision:'',firstBudget:0,aiResponse:'',ai:null,critic:{},claims:[],missed:'',teamConclusion:'',persona:'young',time:'lunch',simulationPersona:'young',simulationTime:'lunch',simulationObservation:'',simulationRoute:[],simulationRiskZones:[],consequenceInput:'',consequenceError:false,consequenceModel:null,simulationView:'plan',simulationRiskOpen:'',simulation:null,unexpected:null,newDecision:'',newSelection:{},newSelectedInterventions:{},newBudget:0,decisionChangeType:'',decisionChangeReason:'',changeReason:'',scenario:null,reflection:{},finalScenarioInput:'',finalScenarioError:false,finalScenarios:null,selectedFinalScenario:'',finalReflection:{},finished:false});
let state=load();
function load(){try{const stored=JSON.parse(localStorage.getItem(KEY)||'{}'),loaded={...blank(),...stored};loaded.simulationPersona??=loaded.persona;loaded.simulationTime??=loaded.time;loaded.simulationObservation??=loaded.simulation?.text||'';loaded.simulationRoute??=loaded.simulation?.route||[];loaded.simulationRiskZones??=loaded.simulation?.riskZones||[];loaded.simulationView??='plan';loaded.simulationRiskOpen??='';if(!Object.prototype.hasOwnProperty.call(stored,'newSelection')&&Object.prototype.hasOwnProperty.call(stored,'newSelectedInterventions'))loaded.newSelection=JSON.parse(JSON.stringify(loaded.newSelectedInterventions||{}));if(!Object.prototype.hasOwnProperty.call(stored,'newSelectedInterventions'))loaded.newSelectedInterventions=JSON.parse(JSON.stringify(loaded.newSelection||{}));if(!Object.prototype.hasOwnProperty.call(stored,'decisionChangeReason'))loaded.decisionChangeReason=stored.changeReason||'';if(!Object.prototype.hasOwnProperty.call(stored,'newBudget'))loaded.newBudget=priceList.reduce((sum,item)=>{const x=loaded.newSelection?.[item.id];return sum+(x?.on?Number(item.custom?x.cost??0:x.unit??0)*(item.qty?Number(x.qty||1):1):0)},0);return loaded}catch{return blank()}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const money=n=>'€'+Number(n||0).toLocaleString('en-GB');
const sumFor=sel=>priceList.reduce((sum,item)=>{const x=sel[item.id];if(!x?.on)return sum;const unit=Number(item.custom?(x.cost??0):(x.unit??0));return sum+unit*(item.qty?Number(x.qty||1):1)},0);
const cloneSelection=sel=>JSON.parse(JSON.stringify(sel||{}));
const budgetValid=sel=>sumFor(sel)<=30000&&priceList.every(item=>{const x=sel[item.id];return !x?.on||Number.isFinite(Number(item.custom?x.cost:x.unit))&&(item.custom?x.cost:x.unit)!==null&&(item.custom?x.cost:x.unit)!==undefined});
const answered=key=>String(state.answers[key]||'').trim().length>0;
function openStage(i){if(i>unlocked()){toast('Complete the previous stage first.');return}state.view='stage';state.stage=i;save();render();window.scrollTo(0,0)}
function unlocked(){return Math.min(state.aiResponse?.trim()?7:2,state.completed.length)}
function complete(next){if(!state.completed.includes(state.stage))state.completed.push(state.stage);state.view='stage';state.stage=Math.min(next,7);save();render();window.scrollTo(0,0)}
function topbar(){const s=stages[state.stage]||stages[7];return `<header class="topbar"><div class="brand"><span class="brand-mark">E</span><span>EDUCATION 2035 <i>/</i> RETAIL MARKETING SEMINAR</span></div><div class="top-actions"><button class="text-button" data-action="map">← BACK TO JOURNEY</button><span class="stage-count">${s.n} <b>/</b> 08</span></div></header>`}
function pathMap(){return `<div class="journey-map" aria-label="Eight stage journey"><svg class="road-svg" viewBox="0 0 1200 390" preserveAspectRatio="none" aria-hidden="true"><path d="M45 120 C190 110 245 280 390 270 S585 95 735 115 S920 300 1150 242"/><path class="road-center" d="M45 120 C190 110 245 280 390 270 S585 95 735 115 S920 300 1150 242"/></svg>${stages.map((s,i)=>{const pos=[[4,27],[17,62],[31,69],[44,39],[57,27],[70,55],[84,65],[96,44]][i];let done=state.completed.includes(i)&&(i<2||!!state.aiResponse?.trim());let status=done?'done':i===unlocked()?'active':'locked';return `<button class="checkpoint ${status}" style="--x:${pos[0]}%;--y:${pos[1]}%" data-action="checkpoint" data-i="${i}" ${status==='locked'?'title="Complete the previous stage first."':''}><span class="cp-num">${s.n}</span><span class="cp-dot">${status==='done'?'✓':status==='locked'?'·':''}</span><span class="cp-label">${s.title}</span><span class="cp-sub">${status==='locked'?'LOCKED':s.label}</span></button>`}).join('')}</div>`}
function mapView(){return `<main class="map-page"><div class="map-heading"><div><div class="eyebrow">A DECISION-MAKING SEMINAR · 8 CHECKPOINTS</div><h1>One store. <em>Many trade-offs.</em></h1><p>Move through the case, make a decision, challenge it and see what changes.</p></div><div class="map-stamp"><span>YOUR<br>JOURNEY</span><b>${String(state.completed.length).padStart(2,'0')}<small>/08</small></b><i>completed</i></div></div>${pathMap()}<div class="map-bottom"><div class="map-legend"><span><i class="legend-dot blue"></i> CURRENT</span><span><i class="legend-dot green"></i> COMPLETED</span><span><i class="legend-dot muted"></i> LOCKED</span></div><button class="primary" data-action="checkpoint" data-i="${unlocked()}">${state.completed.length?'CONTINUE JOURNEY':'OPEN CASE'} <span>→</span></button></div><div class="case-ribbon"><div class="ribbon-kicker">TODAY’S CASE</div><strong>SAVE THE STORE</strong><span>A city supermarket · Retail / Shopper Marketing</span><i>FIELD NOTE 01</i></div></main>`}
function metrics(){return `<div class="metric-grid">${caseData.metrics.map(([a,b,c])=>`<div class="metric-card"><span>${a}</span><strong>${b}</strong><small>${c}</small></div>`).join('')}</div>`}
function evidenceModal(item){let content='';if(item.facts)content=`<div class="fact-list">${item.facts.map((x,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(x[0])}</b><p>${esc(x[1])}</p></div></article>`).join('')}</div>`;else if(item.segments)content=`<div class="segment-grid">${item.segments.map((x,i)=>`<article class="segment"><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p></article>`).join('')}</div>`;else if(item.price)content=`<div class="fact-list">${priceList.map((x,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(x.name)}</b><p>${esc(x.guide)}</p></div></article>`).join('')}</div><p>Case ranges are guidance only. Enter the amount your team plans to spend and keep the total within €30,000.</p>`;else content=`<ul class="evidence-list">${item.body.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;return `<div class="modal-backdrop" data-action="modal-close"><section class="modal" role="dialog" aria-modal="true" aria-label="${item.title}" data-modal><button class="modal-close" data-action="modal-close" aria-label="Close">×</button><div class="eyebrow">CASE MATERIAL · ${item.tag}</div><h2>${item.title}</h2>${content}<button class="secondary" data-action="modal-close">CLOSE MATERIAL</button></section></div>`}
function caseStage(){let cards=caseData.evidence;return `${stageIntro('01 CASE','SAVE THE STORE',caseData.brief)}${metrics()}<section class="panel brief-panel"><div class="panel-head"><div><span class="eyebrow">THE CONSULTING BRIEF</span><p class="objective">${caseData.objective}</p></div><div class="case-index">CASE<br><b>01</b></div></div></section><section class="section-block"><div class="section-heading"><div><span class="eyebrow">OPEN THE FOLDER</span><h2>Evidence before opinion.</h2></div><span class="count-pill">${state.evidence.length} / 5 OPENED <i></i></span></div><div class="evidence-grid">${cards.map((x,i)=>`<button class="evidence-card ${state.evidence.includes(x.id)?'seen':''}" data-action="evidence" data-id="${x.id}"><span class="evidence-index">0${i+1} <b>${state.evidence.includes(x.id)?'✓':'↗'}</b></span><strong>${x.title}</strong><small>${x.tag}</small><span class="evidence-arrow">${state.evidence.includes(x.id)?'REVIEW':'OPEN FILE'} ↗</span></button>`).join('')}</div></section><div class="stage-footer"><span class="footnote">Open at least three evidence cards to unlock the discussion.</span><button class="primary" data-action="start-discussion" ${state.evidence.length<3?'disabled':''}>START HUMAN DISCUSSION <span>→</span></button></div>`}
function stageIntro(kicker,title,desc){return `<section class="stage-intro"><div class="intro-copy"><span class="eyebrow">${kicker} <i>·</i> FIELDWORK</span><h1>${title}</h1><p>${desc}</p></div><div class="intro-index">${kicker.slice(0,2)}<small>/ 08</small></div></section>`}
function field(id,label,placeholder='',required=true,rows=3){let value=id.startsWith('reflection:')?state.reflection[id.split(':')[1]]||'':id==='decision'?state.decision:id==='newDecision'?state.newDecision:id==='missed'?state.missed:id==='teamConclusion'?state.teamConclusion:id==='changeReason'?state.changeReason:id==='decisionChangeReason'?state.decisionChangeReason||state.changeReason:state.answers[id]||'';let locked=id==='decision'&&!!state.lockedDecision;return `<label class="field"><span>${esc(label)}${required?'<i>*</i>':''}${locked?' <small>· LOCKED</small>':''}</span><textarea data-answer="${id}" rows="${rows}" placeholder="${esc(placeholder)}" ${locked?'readonly':''}>${esc(value)}</textarea></label>`}
function budgetBuilder(sel,type){let total=sumFor(sel);let pc=Math.min(120,total/30000*100);let frozen=type==='first'&&!!state.lockedDecision;return `<section class="budget-builder"><div class="section-heading compact"><div><span class="eyebrow">BUDGET BUILDER</span><h2>Build your solution.</h2></div><span class="estimate-label">INDICATIVE CASE PRICES</span></div><p class="estimate-note">Enter the amount your team plans to spend. Case ranges are guidance only; no price is filled in automatically.</p><div class="intervention-list">${priceList.map(item=>{let x=sel[item.id]||{};let on=!!x.on,raw=item.custom?x.cost:x.unit,estimated=raw!==null&&raw!==undefined,unit=Number(raw??0),qty=Number(x.qty||1),subtotal=unit*(item.qty?qty:1);return `<article class="intervention ${on?'selected':''}"><label class="toggle-row"><input type="checkbox" data-budget="${type}" data-id="${item.id}" ${on?'checked':''} ${frozen?'disabled':''}><span class="checkmark"></span><span class="option-copy"><b>${esc(item.name)}</b><small>${esc(item.detail)}</small><small class="price-guide">${esc(item.guide||'COST NOT PROVIDED IN CASE — ENTER TEAM ESTIMATE')}</small></span><span class="option-price">${on?(estimated?money(subtotal):'ESTIMATE NEEDED'):'ADD TO PLAN'}</span></label>${on?`<div class="cost-controls"><label class="cost-input-label">${item.qty?'UNIT ESTIMATE':'ESTIMATED COST'} <span class="cost-number">${estimated?money(unit):'PENDING'}</span><input type="number" min="0" max="30000" step="100" value="${estimated?unit:''}" placeholder="0" data-${item.custom?'cost':'unit'}="${type}" ${frozen?'disabled':''} data-id="${item.id}"></label>${item.qty?`<div class="quantity"><span>QUANTITY</span><button data-action="qty" data-type="${type}" data-id="${item.id}" data-delta="-1" ${frozen?'disabled':''}>−</button><b>${qty}</b><button data-action="qty" data-type="${type}" data-id="${item.id}" data-delta="1" ${frozen?'disabled':''}>+</button></div>`:''}<strong class="subtotal">SUBTOTAL <b>${money(subtotal)}</b></strong></div>`:''}</article>`}).join('')}</div><div class="budget-meter ${total>30000?'over':total>=24000?'near':''}"><div><span>CURRENT BUDGET</span><b>${money(total)} <i>/ ${money(30000)}</i></b></div><div class="meter-track"><span style="width:${pc}%"></span></div>${!budgetValid(sel)?'<strong class="budget-warning">Add an estimate for every selected item to confirm this plan.</strong>':total>30000?'<strong class="budget-warning">BUDGET EXCEEDED — reduce the plan to continue.</strong>':''}</div></section>`}
function newPlanBudgetBuilder(sel){let total=sumFor(sel),pc=Math.min(120,total/30000*100);return `<section class="budget-builder new-plan-budget-builder"><div class="section-heading compact"><div><span class="eyebrow">BUDGET BUILDER</span><h2>Use the case price guide.</h2></div><span class="estimate-label">INDICATIVE CASE PRICES</span></div><p class="estimate-note">Enter the amount your team plans to spend. Case ranges are guidance only; no price is filled in automatically.</p><div class="intervention-list">${priceList.map(item=>{const x=sel[item.id]||{},on=!!x.on,raw=item.custom?x.cost:x.unit,estimated=raw!==null&&raw!==undefined,unit=Number(raw??0),qty=Number(x.qty||1),subtotal=unit*(item.qty?qty:1),guide=item.guide?`CASE PRICE GUIDE · ${item.guide}`:'COST NOT PROVIDED IN CASE — ENTER TEAM ESTIMATE';return `<article class="intervention ${on?'selected':''}"><label class="toggle-row"><input type="checkbox" data-budget="new" data-id="${item.id}" ${on?'checked':''}><span class="checkmark"></span><span class="option-copy"><b>${esc(item.name)}</b><small>${guide?esc(guide):'COST NOT PROVIDED IN CASE — ENTER TEAM ESTIMATE'}</small></span><span class="option-price">${on?(estimated?money(subtotal):'ESTIMATE NEEDED'):'ADD TO PLAN'}</span></label>${on?`<div class="cost-controls"><label class="cost-input-label">${item.qty?'UNIT ESTIMATE':item.id==='promoZone'?'PLANNED TOTAL':'TEAM ESTIMATE'} <span class="cost-number">${estimated?money(unit):'PENDING'}</span><input type="number" min="0" max="30000" step="100" value="${estimated?unit:''}" placeholder="Enter team estimate" data-${item.custom?'cost':'unit'}="new" data-id="${item.id}"></label>${item.qty?`<div class="quantity"><span>QUANTITY</span><button data-action="qty" data-type="new" data-id="${item.id}" data-delta="-1">−</button><b>${qty}</b><button data-action="qty" data-type="new" data-id="${item.id}" data-delta="1">+</button></div>`:''}<strong class="subtotal">SUBTOTAL <b>${money(subtotal)}</b></strong></div>`:''}</article>`}).join('')}</div><div class="budget-meter ${total>30000?'over':total>=24000?'near':''}"><div><span>NEW PLAN BUDGET</span><b>${money(total)} <i>/ ${money(30000)}</i></b></div><div class="meter-track"><span style="width:${pc}%"></span></div>${!budgetValid(sel)?'<strong class="budget-warning">Add an estimate for every selected item to confirm this plan.</strong>':total>30000?'<strong class="budget-warning">BUDGET EXCEEDED — reduce the plan to continue.</strong>':''}</div></section>`}
function discussionStage(){let ok=discussionQuestions.every(([id])=>answered(id))&&state.decision.trim()&&budgetValid(state.selection);return `${stageIntro('02 HUMAN DISCUSSION','THINK BEFORE ASKING AI','Build your first solution without AI. Start with what your team notices, then make a decision you can stand behind.')}<div class="discussion-layout"><section class="panel question-panel"><div class="panel-head"><div><span class="eyebrow">TEAM DISCUSSION</span><h2>Diagnose the store.</h2></div><span class="handwritten">Your own words first</span></div><div class="question-list">${discussionQuestions.map(([id,label],i)=>field(id,`${i+1}. ${label}`,'Discuss with your team…',true,2)).join('')}</div></section><aside class="side-note"><span class="eyebrow">KEEP IN VIEW</span><h3>One choice can help one shopper and slow another down.</h3><p>Think about sales, speed, customer flow, store space and time of day. The building stays as it is; the team cannot grow significantly.</p><div class="note-mark">↗</div></aside></div>${budgetBuilder(state.selection,'first')}<section class="panel decision-editor"><div class="panel-head"><div><span class="eyebrow">YOUR ORIGINAL PRE-AI CHOICE</span><h2>First decision</h2></div><span class="lock-stamp">LOCKS AFTER CONFIRMATION</span></div>${field('decision','Describe your solution. What will you change, why, and how will it improve the customer experience?','We will…',false,5)}<details class="case-example"><summary>OPEN A FIRST-DECISION EXAMPLE FROM THE CASE <span>＋</span></summary><ul>${caseData.examples.firstDecision.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>This is one example from the case, not a preferred answer.</p></details><div class="decision-submit"><div><span class="eyebrow">ESTIMATED PLAN COST</span><b class="decision-total ${sumFor(state.selection)>30000?'red':''}">${money(sumFor(state.selection))} <small>/ €30,000</small></b></div><button class="primary" data-action="submit-first" ${ok?'':'disabled'}>SUBMIT FIRST DECISION <span>→</span></button></div></section>`}
function budgetSummary(sel){let list=priceList.filter(x=>sel[x.id]?.on).map(item=>{let x=sel[item.id],qty=Number(x.qty||1),unit=item.custom?Number(x.cost||0):Number(x.unit??item.min);return `<li>${esc(item.name)}${item.qty?` × ${qty}`:''}<b>${money(unit*(item.qty?qty:1))}</b></li>`});return `<div class="budget-summary"><span class="eyebrow">BUDGET</span>${list.length?`<ul>${list.join('')}</ul>`:'<p>No priced interventions selected yet.</p>'}<strong>TOTAL <b>${money(sumFor(sel))}</b></strong></div>`}
function buildCriticPrompt(){const selected=priceList.filter(item=>state.selection[item.id]?.on);const lines=selected.length?selected.map(item=>{const x=state.selection[item.id],qty=Number(x.qty||1),raw=item.custom?x.cost:x.unit,estimated=raw!==null&&raw!==undefined,unit=Number(raw??0),subtotal=unit*(item.qty?qty:1);return `- ${item.name}${item.qty?` × ${qty}`:''}: ${estimated?money(subtotal):'team estimate not entered'}`}).join('\n'):'- No interventions selected';return `You are analysing a retail marketing decision made by a student team.\n\nCASE:\nA supermarket has declining sales, lower average basket value, long peak-hour queues, difficult navigation, an overloaded ready-to-eat area, different needs of younger and older customers, a €30,000 budget, no store expansion and limited staff growth.\n\nOUR FIRST DECISION:\n${state.lockedDecision||state.decision||'No first decision recorded.'}\n\nOUR SELECTED INTERVENTIONS AND BUDGET:\n${lines}\nTotal: ${money(state.firstBudget||sumFor(state.selection))} of €30,000\n\nDo not solve the case for us and do not replace our decision.\n\nAnalyse OUR decision and return exactly these sections:\n\n1. STRENGTHS\n2. RISKS\n3. WEAKNESSES / HIDDEN ASSUMPTIONS\n4. ALTERNATIVES\n5. FORECAST / POSSIBLE CONSEQUENCES\n\nFor every point, explain why.\nBe critical and specific to our actual decision.`}
function analysisStage(){const saved=!!state.aiResponse?.trim();return `${stageIntro('03 AI ANALYSIS','LET AI CHALLENGE YOUR DECISION','Use an AI tool as a critic of your team’s original choice. You control the prompt and decide what response to bring into the seminar.')}<div class="ai-layout"><section class="panel first-decision-card"><span class="eyebrow">YOUR FIRST DECISION</span><blockquote>${esc(state.lockedDecision||state.decision||'Your decision will appear here.')}</blockquote><div class="decision-meta"><span>ORIGINAL CHOICE · LOCKED</span><span>${money(state.firstBudget||sumFor(state.selection))} ESTIMATED</span></div></section>${budgetSummary(state.selection)}</div><div class="analysis-input-note"><span class="eyebrow">ANALYSIS INPUTS</span><b>First decision + selected interventions + ${money(state.firstBudget||sumFor(state.selection))} estimated budget</b></div><section class="critic-prompt panel"><div class="panel-head"><div><span class="eyebrow">USE AI AS A CRITIC</span><h2>Take your decision to an AI tool.</h2></div><span class="lock-stamp">${saved?'RESPONSE SAVED':'YOUR DECISION INSERTED'}</span></div><label class="field prompt-field"><span>GENERATED PROMPT · READ ONLY</span><textarea class="prompt-text" rows="18" readonly aria-label="Generated AI critique prompt">${esc(buildCriticPrompt())}</textarea></label><div class="prompt-actions"><span class="footnote">The prompt includes your locked decision and budget builder selections.</span><button class="secondary" data-action="copy-prompt">COPY PROMPT</button></div></section><p class="ai-paste-instruction">Paste this prompt into the AI tool you normally use. Then paste its complete response below.</p><section class="panel response-panel"><label class="field"><span>PASTE YOUR AI RESPONSE</span><textarea class="response-text" data-ai-response rows="12" placeholder="Paste the complete response from your AI tool here…" ${saved?'readonly':''}>${esc(state.aiResponse||'')}</textarea></label><div class="response-submit"><span class="footnote">Your response is saved in this browser for this session.</span><button class="primary" data-action="save-ai-response" ${saved||!state.aiResponse?.trim()?'disabled':''}>${saved?'RESPONSE SAVED ✓':'SAVE AI RESPONSE'} <span>${saved?'':'→'}</span></button></div></section>`}
function parseAiResponse(text){const titles=['STRENGTHS','RISKS','WEAKNESSES / HIDDEN ASSUMPTIONS','ALTERNATIVES','FORECAST / POSSIBLE CONSEQUENCES'];const patterns=[/^\s*(?:#{1,6}\s*)?(?:1\s*[.)-]\s*)?STRENGTHS\s*:?.*$/i,/^\s*(?:#{1,6}\s*)?(?:2\s*[.)-]\s*)?RISKS\s*:?.*$/i,/^\s*(?:#{1,6}\s*)?(?:3\s*[.)-]\s*)?WEAKNESSES\s*\/\s*HIDDEN ASSUMPTIONS\s*:?.*$/i,/^\s*(?:#{1,6}\s*)?(?:4\s*[.)-]\s*)?ALTERNATIVES\s*:?.*$/i,/^\s*(?:#{1,6}\s*)?(?:5\s*[.)-]\s*)?FORECAST\s*\/\s*POSSIBLE CONSEQUENCES\s*:?.*$/i];const lines=String(text).split(/\r?\n/),starts=[];lines.forEach((line,index)=>{const section=patterns.findIndex(p=>p.test(line));if(section!==-1)starts.push({section,index})});if(!starts.length)return titles.map((title,i)=>({id:`response-${i+1}`,title,text:i===0?String(text).trim():'Not included in the pasted response.'}));return titles.map((title,i)=>{const start=starts.find(x=>x.section===i);if(!start)return {id:`response-${i+1}`,title,text:'Not included in the pasted response.'};const next=starts.find(x=>x.index>start.index);const body=lines.slice(start.index+1,next?.index??lines.length).join('\n').trim();return {id:`response-${i+1}`,title,text:body||'No points provided in this section.'}})}
async function copyCriticPrompt(button){const prompt=buildCriticPrompt();try{await navigator.clipboard.writeText(prompt)}catch{const helper=document.createElement('textarea');helper.value=prompt;helper.setAttribute('readonly','');helper.style.position='fixed';helper.style.opacity='0';document.body.append(helper);helper.select();document.execCommand('copy');helper.remove()}const original='COPY PROMPT';button.textContent='COPIED ✓';setTimeout(()=>{if(button.isConnected)button.textContent=original},1800)}
function claimCards(){const stored=Array.isArray(state.claims)?state.claims:[];const count=Math.max(3,Math.min(5,stored.length));return Array.from({length:count},(_,i)=>({id:`claim-${i+1}`,text:'',choice:'',why:'',...(stored[i]||{})}))}
function claimControls(claim,index){if(!String(claim.text||'').trim())return '';const whyLabel=claim.choice==='accept'?'Why do you consider this claim convincing? What evidence supports it?':claim.choice==='question'?'What information or evidence would you need before trusting this claim?':claim.choice==='reject'?'Why do you disagree with this claim? What did AI misunderstand?':'';return `<div class="classify-row">${[['accept','ACCEPT'],['question','QUESTION'],['reject','REJECT']].map(([id,label])=>`<button class="choice-chip ${claim.choice===id?'chosen':''}" data-action="critic-choice" data-id="${index}" data-choice="${id}">${label}</button>`).join('')}</div>${claim.choice?`<label class="field explain-field"><span>${whyLabel}<i>*</i></span><textarea rows="3" data-claim-why="${index}" placeholder="Explain your judgement…">${esc(claim.why)}</textarea></label>`:''}`}
