  if(persona==='family'&&(!usePlan||!f.promoChanged))risks.push({id:'promo',title:'PROMO DETOUR',detail:'Promotional stands can slow a larger shop near this aisle.',type:'risk'});
  if(time==='evening')risks.push({id:'staffedCheckout',title:'QUEUE PRESSURE',detail:'Evening peak creates increased checkout demand.',type:'risk'});
  if(usePlan&&time==='morning'&&persona==='older'&&f.timeIncentives)risks.push({id:'staples',title:'MORNING ACTIVITY',detail:'The selected time-based offer may shift older-customer visits into the morning.',type:'activity'});
