  if(usePlan){if(f.movedReady)improvedZones.push('ready');if(f.navigation)improvedZones.push(...route.filter(x=>x.startsWith('aisle')));if(f.express&&route.includes('express'))improvedZones.push('express');if(f.selfCheckout)improvedZones.push('selfCheckout');if(f.flexCheckout&&time==='evening')improvedZones.push('staffedCheckout');if(f.promoChanged&&persona==='family')improvedZones.push('promo');if(f.lunchFlow&&persona==='lunch'&&time==='lunch')improvedZones.push('ready');if(f.timeIncentives&&persona==='older'&&time==='morning')improvedZones.push('staples');}
  const pathPoints=[];
