  const affected=comparison.changed?(view==='plan'?effects.join(' '):`OUR PLAN: ${effects.join(' ')}`):'This part of the experience remains close to the baseline because the team did not select an intervention affecting it. Your current decision does not significantly change this customer’s journey.';
