  const zoneMarkup=Object.entries(boxes).map(([id,[x,y,w,h]])=>{const c=captions[id],isAisle=id.startsWith('aisle'),isReady=id==='ready';return `<g class="floor-zone"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" class="${zoneClass(id)}"/><text x="${x+w/2}" y="${isAisle?y+h/2+25:id==='staples'?y+39:isReady?y+38:y+h/2+4}" text-anchor="middle" class="zone-label ${isAisle?'aisle-label':''}">${c}</text>${isReady?`<text x="${x+w/2}" y="${y+53}" text-anchor="middle" class="sub-label">${view==='plan'&&simulationFlags().movedReady?'MOVED NEAR ENTRANCE':'READY-TO-EAT AREA'}</text>`:''}</g>`}).join('');
