function comparisonFacts(){let critic=state.ai?.map(x=>{let c=state.critic[x.id];return c?`${x.title}: ${c.choice.toUpperCase()} — ${c.why}`:''}).filter(Boolean)[0]||'AI analysis reviewed';return `<div class="facts-stack"><article><span>IMPORTANT AI INSIGHT</span><p>${esc(critic)}</p></article><article><span>WHAT THE TEAM NOTICED</span><p>${esc(state.missed||'Not recorded')}</p></article><article><span>KEY SIMULATION CONSEQUENCE</span><p>${esc(state.simulation?.title||'The shopper route was modelled.')}</p></article><article><span>UNEXPECTED EVENT</span><p>${esc(state.unexpected?.text||'No event recorded')}</p></article></div>`}
